use std::fs

struct Tree {
    keys: Vec<int>,
    lefts: Vec<int>,
    rights: Vec<int>,
    root: int,
}

impl Tree {
    fn insert(self, x: int) -> bool {
        if self.root < 0 {
            self.keys.push(x)
            self.lefts.push(-1)
            self.rights.push(-1)
            self.root = 0
            return true
        }
        let mut cur: int = self.root
        loop {
            let k = self.keys[cur]
            if x == k {
                return false
            }
            if x < k {
                let l = self.lefts[cur]
                if l < 0 {
                    let id: int = self.keys.len()
                    self.keys.push(x)
                    self.lefts.push(-1)
                    self.rights.push(-1)
                    self.lefts[cur] = id
                    return true
                }
                cur = l
            } else {
                let r = self.rights[cur]
                if r < 0 {
                    let id: int = self.keys.len()
                    self.keys.push(x)
                    self.lefts.push(-1)
                    self.rights.push(-1)
                    self.rights[cur] = id
                    return true
                }
                cur = r
            }
        }
        false
    }

    fn contains(self, x: int) -> bool {
        let mut cur: int = self.root
        while cur >= 0 {
            let k = self.keys[cur]
            if x == k {
                return true
            }
            if x < k {
                cur = self.lefts[cur]
            } else {
                cur = self.rights[cur]
            }
        }
        false
    }

    fn set_child(self, parent: int, old: int, new: int) {
        if parent < 0 {
            self.root = new
        } else if self.lefts[parent] == old {
            self.lefts[parent] = new
        } else {
            self.rights[parent] = new
        }
    }

    fn delete(self, x: int) -> bool {
        let mut parent: int = -1
        let mut cur: int = self.root
        while cur >= 0 {
            let k = self.keys[cur]
            if x == k {
                break
            }
            parent = cur
            if x < k {
                cur = self.lefts[cur]
            } else {
                cur = self.rights[cur]
            }
        }
        if cur < 0 {
            return false
        }
        let l = self.lefts[cur]
        let r = self.rights[cur]
        if l < 0 {
            self.set_child(parent, cur, r)
        } else if r < 0 {
            self.set_child(parent, cur, l)
        } else {
            let mut sp: int = cur
            let mut s: int = r
            while self.lefts[s] >= 0 {
                sp = s
                s = self.lefts[s]
            }
            self.keys[cur] = self.keys[s]
            let sr = self.rights[s]
            self.set_child(sp, s, sr)
        }
        true
    }

    fn inorder(self) -> Vec<int> {
        let mut out: Vec<int> = []
        let mut stack: Vec<int> = []
        let mut cur: int = self.root
        while cur >= 0 || stack.len() > 0 {
            while cur >= 0 {
                stack.push(cur)
                cur = self.lefts[cur]
            }
            let n = stack.pop().unwrap_or(-1)
            out.push(self.keys[n])
            cur = self.rights[n]
        }
        out
    }

    fn height(self) -> int {
        if self.root < 0 {
            return 0
        }
        let mut best: int = 0
        let mut nodes: Vec<int> = [self.root]
        let mut depths: Vec<int> = [1]
        while nodes.len() > 0 {
            let n = nodes.pop().unwrap_or(-1)
            let d = depths.pop().unwrap_or(0)
            if d > best {
                best = d
            }
            if self.lefts[n] >= 0 {
                nodes.push(self.lefts[n])
                depths.push(d + 1)
            }
            if self.rights[n] >= 0 {
                nodes.push(self.rights[n])
                depths.push(d + 1)
            }
        }
        best
    }

    fn min_key(self) -> int {
        let mut cur: int = self.root
        while self.lefts[cur] >= 0 {
            cur = self.lefts[cur]
        }
        self.keys[cur]
    }

    fn max_key(self) -> int {
        let mut cur: int = self.root
        while self.rights[cur] >= 0 {
            cur = self.rights[cur]
        }
        self.keys[cur]
    }
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut t = Tree { keys: [], lefts: [], rights: [], root: -1 }
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 {
            continue
        }
        let cmd = parts[0]
        let mut arg: int = 0
        if parts.len() > 1 {
            arg = parts[1].parse::<int>().unwrap_or(0)
        }
        if cmd == "insert" {
            if t.insert(arg) { println("ok") } else { println("dup") }
        } else if cmd == "contains" {
            if t.contains(arg) { println("yes") } else { println("no") }
        } else if cmd == "delete" {
            if t.delete(arg) { println("ok") } else { println("missing") }
        } else if cmd == "inorder" {
            if t.root < 0 {
                println("<empty>")
            } else {
                let strs: Vec<string> = t.inorder().map(|x| "${x}").collect()
                println(strs.join(" "))
            }
        } else if cmd == "height" {
            println("${t.height()}")
        } else if cmd == "min" {
            if t.root < 0 { println("empty") } else { println("${t.min_key()}") }
        } else if cmd == "max" {
            if t.root < 0 { println("empty") } else { println("${t.max_key()}") }
        }
    }
}

